/// <summary>
/// CB731_LaserNetBundleTOMultithreadBatch.
/// This is a task service class for order shipment bundling report.
/// </summary>
class METOrderShipmentBundlingReportingJobTaskService extends METSysOperationTaskService
{
    private SRSPrintDestinationSettings printDestinationSettings;
	private RefRecId salesOrderShipmentLoadHeaderRecId;
    private NoYesId isDangerousGoods;
    private guid topPickingProcessId;
    private int  processedCount;
    private str  shipmentList;
}

Method.Source:
/// <summary>
///  Initializes the object.
/// </summary>
protected void initialise()
{
    METOrderShipmentBundlingReportingJobContract contract;

    super();

    // get the topPickingProcessId from the contract
    contract                 = dataContract as METOrderShipmentBundlingReportingJobContract;
    topPickingProcessId      = contract.parmTopPickingProcessId();
    printDestinationSettings = contract.getPrintDestinationSettings();
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METOrderShipmentBundlingReportingJobContract</c>.
/// </param>
public void process(METOrderShipmentBundlingReportingJobContract _contract)
{
    METProcMetrics procMetrics;

    if (_contract.parmTranscationType() == METOrderTransactionType::SalesOrder)
    {
        procMetrics = METProcMetrics::construct(METBatchLogOperation::SalesOrderShipmentBundling);
        procMetrics.beginTrace("@MET:METSOShipmentBundleReport");
    }
    else
    {
        procMetrics = METProcMetrics::construct(METBatchLogOperation::TransferOrderShipmentBundling);
        procMetrics.beginTrace("@MET:METTOShipmentBundleReport");
    }

    using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
    {
        this.processInternal(_contract);
        procMetrics.incProcessedCount(processedCount);

        if (shipmentList)
        {
            procMetrics.parmDescription(shipmentList);
        }
        procMetrics.endTrace();
    }
}

/// <summary>
/// Runs tasks of the task service class.
/// </summary>
/// <param name = "_readPast">Table read past setting</param>
protected void processTask(boolean _readPast)
{
    while (this.getDataFromTopPickingQueue(topPickingProcessId, _readPast))
    {
        try
        {
            processedCount++;
            this.processReport();
        }
        catch (Exception::Error)
        {
            ttsBegin;

            METSalesOrderShipmentLoadHeader shipment = METSalesOrderShipmentLoadHeader::findByRecId(salesOrderShipmentLoadHeaderRecId,true);

            if (shipment)
            {
                shipment.LaserNetInProgress = NoYes::No;
                shipment.update();
            }

            ttsCommit;
            // Catch any exception so that any one error won't bring down
            // the entire process of sales order substitution.
            Global::exceptionTextFallThrough();
        }
    }
}

/// <summary>
/// Gets data to reserve event orders.
///</summary>
/// <param name = "_processId">Guid created and added in the contract <c>METReserveEventOrdersContract</c>.</param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>True, if data is retrieved from the queue; otherwise; false.</returns>
private boolean getDataFromTopPickingQueue(guid _processId, boolean _readPast)
{
    #OCCRetryCount

    METOrderShipmentBundlingReportingJobQueue topPickingQueue;
    int                                       backOffWait;

    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    topPickingQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock topPickingQueue
            where topPickingQueue.ProcessId == _processId;

        if (topPickingQueue.RecId)
        {
            salesOrderShipmentLoadHeaderRecId = topPickingQueue.SalesOrderShipmentLoadHeaderRecId;
            isDangerousGoods = topPickingQueue.IsDangerousGoods;
            topPickingQueue.delete();
        }
        else
        {
            salesOrderShipmentLoadHeaderRecId = 0;
            isDangerousGoods = NoYes::No;
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return (salesOrderShipmentLoadHeaderRecId != 0);
}

/// <summary>
/// Processes report.
/// </summary>
private void processReport()
{ 
    METSalesOrderShipmentLoadHeader salesOrderShipmentLoadHeader = METSalesOrderShipmentLoadHeader::findByRecId(salesOrderShipmentLoadHeaderRecId, true);

    SrsReportRunController c = new SrsReportRunController();

    if (salesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::SalesOrder)
    {
        c.parmReportName(ssrsReportStr(METSalesOrderShipmentBundlingReport, NewReport));
    }
    else
    {
        c.parmReportName(ssrsReportStr(METTransferOrderShipmentBundlingReport, Report));
    }

    c.parmExecutionMode(SysOperationExecutionMode::Synchronous);
    c.parmShowDialog(false);

    if (printDestinationSettings)
    {
        c.parmReportContract().parmPrintSettings(printDestinationSettings);
    }

    shipmentList = shipmentList + salesOrderShipmentLoadHeader.ShipmentId + ', ';
    METOrderShipmentBundlingReportContract contract = c.parmReportContract().parmRdpContract();

    info(strFmt("@MET:METLasernetReportTrack", salesOrderShipmentLoadHeader.ShipmentId, salesOrderShipmentLoadHeader.LoadId));

    contract.parmLoadId(salesOrderShipmentLoadHeader.LoadID);
    contract.parmShipmentId(salesOrderShipmentLoadHeader.ShipmentID);
    contract.parmTransactionType(salesOrderShipmentLoadHeader.TransactionType);

    c.startOperation();

    if (salesOrderShipmentLoadHeader)
    {
        METSalesOrderShipmentLoadHeader salesOrderShipmentLoadHeaderLoc = METSalesOrderShipmentLoadHeader::findByRecId(salesOrderShipmentLoadHeaderRecId, true);
        ttsbegin;

        salesOrderShipmentLoadHeaderLoc.SentToLaserNet = NoYes::Yes;
        salesOrderShipmentLoadHeaderLoc.LaserNetInProgress = NoYes::No;
        salesOrderShipmentLoadHeaderLoc.update();

        ttscommit;
    }
}
